"""Inert quadratic fake-core test only; no project/model/encoder/core invocation."""
import hashlib,importlib.util,json,sys,types
from pathlib import Path
import numpy as np
ROOT=Path.cwd()
path=ROOT/'experiments/r4_integrated/real_input_numerical_check.py'
spec=importlib.util.spec_from_file_location('check_under_test',path)
module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module)
NAMES=('input_weights','recurrent_weights','cell_bias','span_heads','stop_head','stop_bias','attention_weights','query_context_weights')
def ah(a):return hashlib.sha256(a.tobytes()).hexdigest()
class Fake:
    bad_gradient=False
    def __init__(self,**kwargs):
        self._weights={k:np.full((2,),.1) for k in NAMES}
        self._first={k:np.zeros(2) for k in NAMES};self._second={k:np.zeros(2) for k in NAMES}
        self._steps={k:0 for k in NAMES};self.offer_count=self.update_count=0
        self.parameters={'parameter_names':NAMES}
    @property
    def checkpoint_sha256(self):return hashlib.sha256(json.dumps([self.offer_count,self.update_count,self._steps,*[{k:ah(v) for k,v in block.items()} for block in (self._weights,self._first,self._second)]],sort_keys=True).encode()).hexdigest()
    def snapshot(self):return {'checkpoint_sha256':self.checkpoint_sha256,'offer_count':self.offer_count,'update_count':self.update_count}
    def _forward(self,q,i):return self._weights
    def _objective(self,f,gold):return (sum(float(np.square(v).sum())/2 for k,v in f.items() if gold is not None or k!='span_heads'),)
    def loss_and_gradients(self,q,i,gold):
        loss=self._objective(self._weights,gold)[0]
        g={k:v.copy() if gold is not None or k!='span_heads' else np.zeros_like(v) for k,v in self._weights.items()}
        if self.bad_gradient:g['input_weights']+=1
        return loss,g,{'loss':loss}
    def predict(self,q,i):return types.SimpleNamespace(candidate_index=None,stopped=True,p_stop=.5,span_scores=np.zeros(1))
    def observe(self,q,i,gold):
        before=self.checkpoint_sha256;steps=dict(self._steps)
        _,gr,_=self.loss_and_gradients(q,i,gold)
        active=[k for k in NAMES if gold is not None or k!='span_heads']
        norm=float(np.sqrt(sum(float(np.sum(gr[k]**2)) for k in active)));scale=min(1.,1./norm)
        for k in active:
            g=gr[k]*scale;self._steps[k]+=1;t=self._steps[k]
            self._first[k]=.9*self._first[k]+.1*g;self._second[k]=.999*self._second[k]+.001*g*g
            self._weights[k]-=.001*(self._first[k]/(1-.9**t))/(np.sqrt(self._second[k]/(1-.999**t))+1e-8)
        self.offer_count+=1;self.update_count+=1
        return {'before':before,'after':self.checkpoint_sha256,'gradient_sha256':{k:ah(v) for k,v in gr.items()},'gradient_norm':norm,'clip_scale':scale,'active_parameters':active,'adam_steps_before':steps,'adam_steps_after':dict(self._steps),'parameter_update_applied':True,'native_update_applied':False,'offer_count':self.offer_count,'update_count':self.update_count,'query_sha256':q.sha256,'inventory_sha256':i.sha256,'gold_indices':None if gold is None else list(gold)}
for mod,cls in (('humanbrain.conventional_attention_reader','ConventionalAttentionReader'),('humanbrain.query_aligned_rate_cell_reader','QueryAlignedRateCellReader')):
    fake_module=types.ModuleType(mod);setattr(fake_module,cls,Fake);sys.modules[mod]=fake_module
q=types.SimpleNamespace(sha256='synthetic-query');inventory=types.SimpleNamespace(sha256='synthetic-inventory')
passed=module.run_numerical_check((q,inventory,(0,)),(q,inventory,None))
assert passed['status']=='passed',passed.get('error')
assert passed['counts']=={'perturbed_forward':64,'baseline_gradients':4,'predictions':4,'validation_offers':4}
Fake.bad_gradient=True
red=module.run_numerical_check((q,inventory,(0,)),(q,inventory,None))
assert red['status']=='failed' and red['counts']['validation_offers']==0
assert 'finite difference mismatch' in red['error']['message']
Fake.bad_gradient=False
def interrupted(label):
    if label.endswith(':Adam'):raise TimeoutError('synthetic budget stop')
fault=module.run_numerical_check((q,inventory,(0,)),(q,inventory,None),guard=interrupted)
assert fault['status']=='failed' and fault['error']['type']=='TimeoutError'
assert fault['counts']['perturbed_forward']==16 and fault['counts']['validation_offers']==0
assert module._comparison(0.,0.)['passed']
assert not module._comparison(1.,0.)['passed']
receipt={'status':'passed_inert_fake_core_qa','source_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'success_counts':passed['counts'],'injected_gradient_failure':red['error'],'budget_failure':fault['error'],'scope':'Inert quadratic fake-core success, red gradient defect and partial budget failure. No actual core/input/model calls. Numerical qualification remains unexecuted.','checker_source':Path(__file__).read_text(encoding='utf-8')}
out=ROOT/'.pytest-tmp/real-input-numerical-inert-qa.json';assert not out.exists()
out.write_text(json.dumps(receipt,indent=2)+'\n',encoding='utf-8',newline='\n')
