"""Execute actual runner control flow with fake readers/motor/native only."""
import ast
import contextlib
import hashlib
import io
import json
import os
import sys
import tempfile
import types
from dataclasses import dataclass
from pathlib import Path
from unittest.mock import patch

import numpy as np

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / 'experiments/r4_integrated/real_input_qualification.py'
FIXTURE = ROOT / 'experiments/r4_integrated/real_input_qualification_cases_v1.json'
fixture = json.loads(FIXTURE.read_bytes())
rows_by_raw = {bytes.fromhex(r['raw_hex']): r for r in fixture['saved_inputs']}
lessons_by_query = {r['question'].encode(): r for r in fixture['cases']}
lessons_by_doc = {fixture['documents'][r['paragraph_id']]['context'].encode(): r for r in fixture['cases']}
ARMS = ('trainable', 'frozen_producer', 'frozen', 'conventional', 'conventional_frozen', 'external')


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def hash_obj(value):
    return sha(json.dumps(value, sort_keys=True, allow_nan=False).encode())


def scenario(kind):
    counters = dict(predictions=0, offers=0, actions=0, demonstrations=0, allocations=0, numerical=0)
    latest, observed = {}, []
    @dataclass
    class Tokens:
        raw: bytes
        byte_spans: tuple
        vectors: object
        encoder_sha256: str

        def __post_init__(self):
            self.sha256 = hash_obj(dict(raw=self.raw.hex(), spans=self.byte_spans,
                vectors=sha(self.vectors.tobytes()), encoder=self.encoder_sha256,
                policy='unicode_regex_words;float32_subtoken_mean;float64_L2_max1e-12'))
    @dataclass
    class Document:
        document_id: bytes
        provenance_id: bytes
        tokens: object
    class Inventory:
        def __init__(self, documents):
            self.sha256 = hash_obj(dict(policy='rate_cell_word_span_hierarchical_stop_v1',
                window_words=48, documents=[(d.document_id.hex(), d.provenance_id.hex(), d.tokens.sha256) for d in documents]))
            lesson = lessons_by_doc[documents[0].tokens.raw]
            answer = b'synthetic_wrong' if lesson['is_impossible'] else bytes.fromhex(lesson['accepted_text_hex'][0])
            self.candidates = (types.SimpleNamespace(emitted=answer), types.SimpleNamespace(emitted=b'synthetic_wrong'))
    class Core:
        def __init__(self, arm):
            counters['allocations'] += 1
            self.arm, self.offer_count = arm, 0
        @property
        def checkpoint_sha256(self):
            return f'{self.arm}:{self.offer_count}'
        def checkpoint_arrays(self):
            return {'state': np.asarray([self.offer_count], dtype=np.float64)}
        def snapshot(self):
            return dict(checkpoint_sha256=self.checkpoint_sha256, offer_count=self.offer_count)
        def predict(self, query, inventory, external=False):
            counters['predictions'] += 1
            lesson = lessons_by_query[query.raw]
            stopped = lesson['is_impossible']
            chosen = None if stopped else 0 if self.offer_count else 1
            scores = np.array([1., 0.]) if chosen != 1 else np.array([0., 1.])
            if kind == 'probe_mutation' and self.arm == 'trainable':
                self.offer_count += 1
            pred = types.SimpleNamespace(candidate_index=chosen, stopped=stopped,
                p_stop=.8 if stopped else .1, stop_logit=1. if stopped else -1.,
                span_scores=scores, stop_reason='answerability_STOP' if stopped else None,
                checkpoint_sha256=self.checkpoint_sha256, query_sha256=query.sha256,
                inventory_sha256=inventory.sha256, external=external)
            latest[(id(self), query.raw, external)] = pred
            return pred
        def external_only(self, query, inventory):
            return self.predict(query, inventory, True)
        def observe(self, query, inventory, gold):
            parent = self.checkpoint_sha256
            self.offer_count += 1
            counters['offers'] += 1
            observed.append((self.arm, lessons_by_query[query.raw]['id']))
            return dict(before=parent, after=self.checkpoint_sha256, parameter_update_applied=True)
    def new_cores():
        cores = {a: Core(a) for a in ARMS[:4]}
        cores['external'] = cores['frozen']
        return cores
    @dataclass
    class Task:
        name: str
        action_instruction: bytes
        key: str
        module: str
        stale: str
        expected_answer: bytes | None
    def execute_prediction(prediction, query, inventory, motor, task, root, *, reader):
        counters['actions'] += 1
        arm, ordinal = task.name.rsplit('-', 1)
        i = int(ordinal)
        assert task.action_instruction == f'Configure qa{i:03d}'.encode()
        assert task.key == f'qa{i:03d}' and task.module == f'qa_config{i:03d}' and task.stale == 'pending'
        assert query.raw == fixture['cases'][i]['question'].encode()
        assert prediction is latest[(id(reader), query.raw, arm == 'external')]
        assert prediction.checkpoint_sha256 == reader.checkpoint_sha256
        assert prediction.query_sha256 == query.sha256 and prediction.inventory_sha256 == inventory.sha256
        emitted = None if prediction.stopped else inventory.candidates[prediction.candidate_index].emitted
        return dict(success=emitted == task.expected_answer,
                    expected_answer_hex=None if task.expected_answer is None else task.expected_answer.hex(),
                    execution={'decoys_unchanged': True})
    def motor(work, report):
        counters['demonstrations'] += 2
        report['motor_demonstrations'] = [{'synthetic_demo': i} for i in range(2)]
        return object()
    def numerical(*args, **kwargs):
        counters['numerical'] += 1
        return {'status': 'failed' if kind == 'admission_failure' else 'passed', 'counts': {'synthetic': 1}}
    def summary(rows, supported, unsupported):
        return dict(completed=len(rows), supported=supported, unsupported=unsupported,
                    exact_supported=sum(r['supported'] and r['correct'] for r in rows),
                    correct_stop=sum(not r['supported'] and r['correct'] for r in rows))
    native = json.loads((ROOT / '.pytest-tmp/real-input-native-setup.json').read_bytes())['build']
    modules = {}
    def module(name, **items):
        value = types.ModuleType(name)
        value.__dict__.update(items)
        modules[name] = value
    for name in ('humanbrain', 'experiments', 'experiments.r4_integrated', 'benchmarks'):
        module(name, __path__=[])
    module('benchmarks.native_scaling', _process_memory=lambda: dict(peak_working_set_mib=1))
    module('experiments.r4_integrated.contextual_pairwise_python_session', _motor=motor)
    module('experiments.r4_integrated.public_qa_acquisition', gold_indices=lambda lesson, inv: None if lesson['is_impossible'] else (0,),
           new_cores=new_cores, qa_summary=summary, source_identity=lambda revision: dict(revision=revision, files={}))
    module('experiments.r4_integrated.rate_cell_session_support', retained_size=lambda *args: 0)
    module('experiments.r4_integrated.real_input_action_bridge', ActionTask=Task, execute_prediction=execute_prediction)
    module('experiments.r4_integrated.real_input_numerical_check', run_numerical_check=numerical)
    module('humanbrain.conventional_attention_reader', ConventionalAttentionReader=lambda mode: Core('conventional_frozen'))
    module('humanbrain.native', loaded_build_info=lambda: types.SimpleNamespace(library_path=Path(native['library_path']), source_digest=native['source_digest']))
    module('humanbrain.rate_cell_reader', SpanInventory=Inventory, TokenDocument=Document, TokenInput=Tokens)
    namespace = {'__file__': str(SOURCE), '__name__': 'inert_runner'}
    tree = ast.parse(SOURCE.read_text(encoding='utf-8'))
    body = [n for n in tree.body if not (isinstance(n, ast.If) and isinstance(n.test, ast.Compare))]
    exec(compile(ast.Module(body=body, type_ignores=[]), str(SOURCE), 'exec'), namespace)
    if kind == 'fixture_failure':
        namespace['FIXTURE_HASH'] = 'incorrect-fixture-hash'
    folder = Path(tempfile.mkdtemp(prefix='real-input-runner-qa-', dir=ROOT / '.pytest-tmp'))
    output = folder / 'report.json'
    env = {k: '1' for k in ('OPENBLAS_NUM_THREADS', 'OMP_NUM_THREADS', 'MKL_NUM_THREADS')}
    env.update(HUMANBRAIN_DEVICE='cpu', HUMANBRAIN_NATIVE_CACHE=str(ROOT / '.native-cache'))
    captured = io.StringIO()
    error = None
    def git_bytes(command, **kwargs):
        if kind == 'source_failure':
            return b'synthetic mismatched frozen source'
        return (ROOT / command[-1].removeprefix('HEAD:')).read_bytes()
    with contextlib.ExitStack() as stack:
        stack.enter_context(patch.dict(sys.modules, modules))
        stack.enter_context(patch.dict(os.environ, env))
        stack.enter_context(patch.object(namespace['subprocess'], 'check_output', side_effect=git_bytes))
        stack.enter_context(contextlib.redirect_stdout(captured))
        if kind == 'npz_failure':
            stack.enter_context(patch.object(np, 'savez_compressed', side_effect=OSError('synthetic archive failure')))
        try:
            namespace['run'](output, 'synthetic-source-only')
        except RuntimeError as exc:
            error = str(exc)
    report = json.loads(output.read_bytes())
    completion = json.loads(output.with_suffix('.completion.json').read_bytes())
    if kind == 'success':
        assert error is None and report['status'] == 'completed' and completion['status'] == 'passed'
        assert counters == dict(predictions=2400, offers=12288, actions=96, demonstrations=2, allocations=5, numerical=1), counters
        assert report['decision']['complete'] and report['decision']['qualified']
        expected = []
        for block in ('A', 'B'):
            for _ in range(256):
                for id_ in fixture['blocks'][block]:
                    expected.extend((arm, id_) for arm in ('trainable', 'frozen_producer', 'conventional'))
        assert observed == expected
        assert [r['id'] for r in report['probes']['B_256']['trainable']] == fixture['blocks']['A'] + fixture['blocks']['B']
        missing = json.loads(json.dumps(report)); missing['motor_return']['trainable'].pop()
        assert not namespace['decision'](missing)['complete']
        wrong = json.loads(json.dumps(report)); wrong['training'][1]['id'] = wrong['training'][0]['id']
        assert not namespace['decision'](wrong)['complete']
    else:
        assert error is not None and completion['status'] == 'failed'
        if kind in ('admission_failure', 'fixture_failure', 'source_failure'):
            assert counters['allocations'] == counters['offers'] == counters['actions'] == counters['demonstrations'] == 0
        if kind == 'probe_mutation':
            assert not report['training'] and counters['actions'] == 0
            assert 'probe changed' in report['error']['message']
        if kind == 'npz_failure':
            assert counters['actions'] == 96 and report['finalization_errors']
    return dict(scenario=kind, status='passed', counters=counters, output=str(output),
                report_sha256=sha(output.read_bytes()), completion_sha256=sha(output.with_suffix('.completion.json').read_bytes()),
                partial_status=report['status'], completion_status=completion['status'])


def main():
    output = ROOT / '.pytest-tmp/real-input-runner-qa-v2.json'
    if output.exists():
        raise FileExistsError(output)
    results = [scenario(name) for name in ('success', 'admission_failure', 'fixture_failure', 'source_failure', 'probe_mutation', 'npz_failure')]
    report = dict(status='passed', scope=__doc__, actual_model_encoder_native_motor_or_child_calls=0,
                  source_sha256=sha(SOURCE.read_bytes()), fixture_sha256=sha(FIXTURE.read_bytes()),
                  scenarios=results, checker_sha256=sha(Path(__file__).read_bytes()),
                  checker_source=Path(__file__).read_text(encoding='utf-8'))
    with output.open('x', encoding='utf-8', newline='\n') as stream:
        json.dump(report, stream, separators=(',', ':'), allow_nan=False); stream.write('\n')
    print(json.dumps({k:v for k,v in report.items() if k != 'checker_source'}))


if __name__ == '__main__':
    main()
